import{_ as a,o as t,c as n,ai as o}from"./chunks/framework.Ci0kozOl.js";const g=JSON.parse('{"title":"Digging Deeper","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/advanced/index.md","filePath":"2.0/advanced/index.md","lastUpdated":1778854311000}'),i={name:"2.0/advanced/index.md"};function r(s,e,d,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="digging-deeper" tabindex="-1">Digging Deeper <a class="header-anchor" href="#digging-deeper" aria-label="Permalink to &quot;Digging Deeper&quot;">​</a></h1><p>Welcome to the &quot;Digging Deeper&quot; section of the UnoPim documentation. Here, we will explore various advanced topics related to UnoPim, which will enable you to customize and extend your pim platform to suit your specific needs.</p><p>We expect you to have knowledge of creating packages in Laravel. If you are new to package development, we recommend referring to the <a href="./../packages/create-package.html">Package Development</a> section for a primer on creating and managing packages in Laravel.</p><h3 id="events-and-event-handlers" tabindex="-1">Events and Event Handlers <a class="header-anchor" href="#events-and-event-handlers" aria-label="Permalink to &quot;Events and Event Handlers&quot;">​</a></h3><p>Events and event handlers provide a powerful way to extend the functionality of UnoPim by allowing you to react to specific actions or triggers within the application. We will show you how to utilize events and event handlers effectively, enabling you to integrate custom functionalities and automate processes.</p><h3 id="helpers" tabindex="-1">Helpers <a class="header-anchor" href="#helpers" aria-label="Permalink to &quot;Helpers&quot;">​</a></h3><p>UnoPim includes a comprehensive set of helper functions that simplify common development tasks and enhance productivity. We will explore the various helper functions available, explaining their purpose and usage to assist you in writing clean and efficient code.</p><h3 id="overriding-core-models" tabindex="-1">Overriding Core Models <a class="header-anchor" href="#overriding-core-models" aria-label="Permalink to &quot;Overriding Core Models&quot;">​</a></h3><p>Sometimes, you may need to modify or extend the default behavior of UnoPim&#39;s core models to accommodate your specific business requirements. We will demonstrate how to override core models effectively, enabling you to customize the behavior of UnoPim without modifying the underlying codebase.</p><h3 id="ai-agent-integration" tabindex="-1">AI Agent Integration <a class="header-anchor" href="#ai-agent-integration" aria-label="Permalink to &quot;AI Agent Integration&quot;">​</a></h3><p>UnoPim v2.0.0 introduces the AiAgent package, which provides a conversational AI interface with 32+ PIM-specific tools. We will cover how to use the AI agent chat for product management, configure approval workflows for AI-suggested changes, set up auto-enrichment pipelines, and extend the agent with custom tools.</p><h3 id="magicai-platform-management" tabindex="-1">MagicAI Platform Management <a class="header-anchor" href="#magicai-platform-management" aria-label="Permalink to &quot;MagicAI Platform Management&quot;">​</a></h3><p>The enhanced MagicAI package in v2.0.0 supports 10+ AI providers through a unified configuration interface. We will explain how to configure multi-platform AI providers, manage database-backed credentials, switch between providers, and customize AI behavior for content generation and translation tasks.</p>',13)])])}const m=a(i,[["render",r]]);export{g as __pageData,m as default};
